(()=>{const api="https://twjpjzalyvbsdpbzhqln.supabase.co/functions/v1/public-gtworld";const status=document.querySelector("[data-gtw-status]");const content=document.querySelector("[data-gtw-content]");const standingsBody=document.querySelector("[data-gtw-standings]");const eventsBox=document.querySelector("[data-gtw-events]");if(!status||!content||!standingsBody||!eventsBox)return;const fmtLap=value=>{const ms=Number(value);if(!Number.isFinite(ms)||ms<=0)return"—";const m=Math.floor(ms/6e4);const s=Math.floor(ms%6e4/1e3);const r=Math.floor(ms%1e3);return`${m}:${String(s).padStart(2,"0")}.${String(r).padStart(3,"0")}`};const fmtDate=value=>new Intl.DateTimeFormat("fr-BE",{dateStyle:"medium",timeStyle:"short",timeZone:"Europe/Brussels"}).format(new Date(value));const esc=value=>String(value??"").replace(/[&<>"']/g,(c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c])));fetch(`${api}?ts=${Date.now()}`,{cache:"no-store"}).then((response=>response.ok?response.json():Promise.reject(new Error("load_failed")))).then((data=>{standingsBody.replaceChildren();for(const team of data.standings||[]){const tr=document.createElement("tr");[team.rank,team.team_name,team.points,team.events,team.wins,team.podiums,team.sprint,team.endurance,team.fastest_laps].forEach((value=>{const td=document.createElement("td");td.textContent=String(value??"—");tr.append(td)}));standingsBody.append(tr)}if(!data.standings?.length){const tr=document.createElement("tr");tr.innerHTML='<td colspan="9">Aucune équipe classée pour le moment. Les équipes doivent être associées aux pilotes dans le panneau administrateur.</td>';standingsBody.append(tr)}eventsBox.replaceChildren();for(const event of data.events||[]){const article=document.createElement("article");article.className="gtw-event";const rows=(event.teams||[]).map((team=>`\n          <tr><td>${team.finish_position?`P${team.finish_position}`:"—"}</td><td><strong>${esc(team.team_name)}</strong><div class="gtw-members">${esc((team.members||[]).join(" · ")||"Équipage non renseigné")}</div></td><td>${fmtLap(team.best_lap_ms)}</td><td>${team.fastest_lap_bonus?'<span class="gtw-fast">+2 meilleur tour</span>':"—"}</td><td><strong>${team.points}</strong></td></tr>`)).join("");article.innerHTML=`<header><div><span class="gtw-badge">${esc(event.format)}</span><h3>${esc(event.title)}</h3><div class="gtw-members">${esc(event.circuit_name)} · ${fmtDate(event.starts_at)}</div></div><a class="btn small" href="course.html?event=${encodeURIComponent(event.slug)}">Voir la course</a></header><div class="leaderboard-wrap"><table class="leaderboard-table"><thead><tr><th>Pos.</th><th>Équipe / pilotes</th><th>Meilleur tour</th><th>Bonus</th><th>Points</th></tr></thead><tbody>${rows||'<tr><td colspan="5">Résultats d’équipe en attente.</td></tr>'}</tbody></table></div>`;eventsBox.append(article)}status.hidden=true;content.hidden=false})).catch((()=>{status.textContent="Impossible de charger le classement GT World pour le moment."}))})();